const __pageData = JSON.parse('{"title":"RAG 混合检索工程实践：BM25、向量召回、RRF 与重排序","description":"","frontmatter":{"title":"RAG 混合检索工程实践：BM25、向量召回、RRF 与重排序","date":"2026-08-04T00:00:00.000Z","category":"AI","cover":"/covers/backend.svg","tags":["ai","rag","spring-ai","elasticsearch","bm25","rrf"],"excerpt":"从关键词与向量召回的互补性出发，讲清分数融合、RRF、语义重排的边界，并给出 Spring AI 2.0.0 混合检索实现与评测方法。"},"headers":[],"relativePath":"posts/rag-hybrid-retrieval-rrf.md","filePath":"posts/rag-hybrid-retrieval-rrf.md","lastUpdated":1787128073000}');
